Can you write pytest tests for this module? It's from our lending dashboard. We had a bug in prod last month where the final payment of a schedule was off and nobody noticed for weeks, so I want the tests to actually catch that kind of thing, not just check that the functions return something.

src/lending/amortize.py:

```python
"""Loan amortization schedules for the lending dashboard."""
from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


@dataclass(frozen=True)
class Installment:
    number: int
    payment: Decimal
    interest: Decimal
    principal: Decimal
    balance: Decimal


def monthly_payment(principal: Decimal, annual_rate: Decimal, months: int) -> Decimal:
    if principal <= 0:
        raise ValueError("principal must be positive")
    if months <= 0:
        raise ValueError("months must be positive")
    if annual_rate < 0:
        raise ValueError("annual_rate must not be negative")
    if annual_rate == 0:
        return (principal / months).quantize(CENT, ROUND_HALF_UP)
    r = annual_rate / 12
    factor = (1 + r) ** months
    payment = principal * r * factor / (factor - 1)
    return payment.quantize(CENT, ROUND_HALF_UP)


def schedule(principal: Decimal, annual_rate: Decimal, months: int) -> list[Installment]:
    payment = monthly_payment(principal, annual_rate, months)
    r = annual_rate / 12
    balance = principal
    rows: list[Installment] = []
    for n in range(1, months + 1):
        interest = (balance * r).quantize(CENT, ROUND_HALF_UP)
        if n == months:
            principal_part = balance
            pay = principal_part + interest
        else:
            principal_part = payment - interest
            pay = payment
        balance = balance - principal_part
        rows.append(Installment(n, pay, interest, principal_part, balance))
    return rows


def total_interest(rows: list[Installment]) -> Decimal:
    return sum((row.interest for row in rows), Decimal("0"))
```

The most useful tests here are **invariants** that must hold for any loan (balance ends at exactly zero, principal parts add up to the loan, every amount is whole cents), run over a few very different loans. Add a handful of hand-checked values on top so a formula change can't slip through.

`tests/test_amortize.py`:

```python
from decimal import Decimal as D

import pytest

from lending.amortize import Installment, monthly_payment, schedule, total_interest

# Very different shapes on purpose: short, medium, 30-year mortgage, zero rate.
LOANS = [
    pytest.param(D("10000"), D("0.06"), 12, id="10k-6pct-1y"),
    pytest.param(D("18500"), D("0.0799"), 60, id="18.5k-7.99pct-5y"),
    pytest.param(D("250000"), D("0.045"), 360, id="250k-4.5pct-30y"),
    pytest.param(D("1000"), D("0"), 3, id="zero-rate"),
]


# --- monthly_payment ---------------------------------------------------------

@pytest.mark.parametrize(
    ("principal", "rate", "months", "expected"),
    [
        (D("10000"), D("0.06"), 12, D("860.66")),
        (D("18500"), D("0.0799"), 60, D("375.02")),
        (D("250000"), D("0.045"), 360, D("1266.71")),
        (D("1200"), D("0"), 12, D("100.00")),
        (D("1000"), D("0"), 3, D("333.33")),
    ],
)
def test_monthly_payment_known_values(principal, rate, months, expected):
    assert monthly_payment(principal, rate, months) == expected


@pytest.mark.parametrize(
    ("principal", "rate", "months", "message"),
    [
        (D("0"), D("0.05"), 12, "principal"),
        (D("-100"), D("0.05"), 12, "principal"),
        (D("1000"), D("0.05"), 0, "months"),
        (D("1000"), D("-0.01"), 12, "annual_rate"),
    ],
)
def test_monthly_payment_rejects_bad_input(principal, rate, months, message):
    with pytest.raises(ValueError, match=message):
        monthly_payment(principal, rate, months)


# --- schedule: invariants that must hold for every loan ----------------------

@pytest.mark.parametrize(("principal", "rate", "months"), LOANS)
class TestScheduleInvariants:
    def test_one_row_per_month_numbered_from_one(self, principal, rate, months):
        rows = schedule(principal, rate, months)
        assert [r.number for r in rows] == list(range(1, months + 1))

    def test_ends_at_exactly_zero(self, principal, rate, months):
        assert schedule(principal, rate, months)[-1].balance == 0

    def test_principal_parts_add_up_to_the_loan(self, principal, rate, months):
        rows = schedule(principal, rate, months)
        assert sum(r.principal for r in rows) == principal

    def test_each_payment_is_interest_plus_principal(self, principal, rate, months):
        for row in schedule(principal, rate, months):
            assert row.payment == row.interest + row.principal, row

    def test_balance_never_negative_and_never_grows(self, principal, rate, months):
        balances = [r.balance for r in schedule(principal, rate, months)]
        assert all(b >= 0 for b in balances)
        assert balances == sorted(balances, reverse=True)

    def test_all_amounts_are_whole_cents(self, principal, rate, months):
        for row in schedule(principal, rate, months):
            for value in (row.payment, row.interest, row.principal, row.balance):
                assert value == value.quantize(D("0.01")), (row.number, value)

    def test_regular_payments_match_monthly_payment(self, principal, rate, months):
        rows = schedule(principal, rate, months)
        expected = monthly_payment(principal, rate, months)
        assert {r.payment for r in rows[:-1]} == {expected}


# --- hand-checked rows -------------------------------------------------------

def test_first_installment_breakdown():
    first = schedule(D("10000"), D("0.06"), 12)[0]
    assert first == Installment(1, D("860.66"), D("50.00"), D("810.66"), D("9189.34"))


def test_last_installment_breakdown():
    last = schedule(D("10000"), D("0.06"), 12)[-1]
    assert last == Installment(12, D("860.70"), D("4.28"), D("856.42"), D("0.00"))


def test_zero_rate_last_payment_absorbs_the_odd_cent():
    payments = [r.payment for r in schedule(D("1000"), D("0"), 3)]
    assert payments == [D("333.33"), D("333.33"), D("333.34")]


def test_total_interest():
    assert total_interest(schedule(D("10000"), D("0.06"), 12)) == D("327.96")
    assert total_interest([]) == 0
```

Why these catch the bug you had:

- `test_ends_at_exactly_zero` and `test_principal_parts_add_up_to_the_loan` fail as soon as the last row stops absorbing the leftover balance. Of all the tests here, they are the most likely to catch a regression like last month's.
- `test_all_amounts_are_whole_cents` catches a missing `quantize` (for example someone computing `pay = principal_part + interest` from an unrounded value).
- The class-level `parametrize` runs every invariant against all four loans, so you get 28 separate test results with ids like `test_ends_at_exactly_zero[250k-4.5pct-30y]`.

One thing to decide with the business side before you add a test for it: **the final payment is not "off by a cent"**. It absorbs all the rounding drift of the regular payment, and that drift grows with the term. For the 30-year case the regular payment is 1266.71 and the last one is 1269.32, a difference of 2.61. If the rule is "the last payment may differ by at most one cent", this test documents it, and it will currently fail:

```python
def test_final_payment_within_one_cent_of_regular_payment():
    rows = schedule(D("250000"), D("0.045"), 360)
    assert abs(rows[-1].payment - rows[0].payment) <= D("0.01")
```

If that's the required behaviour, the algorithm has to change (for example round the payment up instead of half-up, or spread the correction over the last few months). The test tells you which loans break the rule.

Use **factory fixtures**: fixtures that return a function, which builds an object with sensible defaults and takes keyword overrides. Each test then only spells out the fields it cares about, and a new required field is a one-line change in `conftest.py`.

`tests/conftest.py`:

```python
import itertools
from datetime import datetime, timezone

import pytest

from boxoffice.models import Event, Ticket, Venue

_seq = itertools.count(1)


@pytest.fixture
def make_venue():
    def _make_venue(**overrides) -> Venue:
        n = next(_seq)
        fields = {"name": f"Venue {n}", "city": "Leipzig", "capacity": 500}
        return Venue(**(fields | overrides))

    return _make_venue


@pytest.fixture
def make_event(make_venue):
    def _make_event(*, venue: Venue | None = None, **overrides) -> Event:
        n = next(_seq)
        fields = {
            "title": f"Event {n}",
            "venue": venue if venue is not None else make_venue(),
            "starts_at": datetime(2030, 6, 1, 20, 0, tzinfo=timezone.utc),
            "price_cents": 2500,
            "organizer_id": 1,
        }
        return Event(**(fields | overrides))

    return _make_event


@pytest.fixture
def make_ticket(make_event):
    def _make_ticket(*, event: Event | None = None, **overrides) -> Ticket:
        fields = {
            "event": event if event is not None else make_event(),
            "holder_email": f"guest{next(_seq)}@example.com",
            "seat": None,
        }
        return Ticket(**(fields | overrides))

    return _make_ticket
```

Your test becomes:

```python
def test_cannot_sell_more_than_capacity(make_venue, make_event):
    event = make_event(venue=make_venue(capacity=2))
    sell_ticket(event, "a@example.com")
    sell_ticket(event, "b@example.com")
    with pytest.raises(SoldOut):
        sell_ticket(event, "c@example.com")


def test_past_events_are_not_on_sale(make_event):
    event = make_event(starts_at=datetime(2020, 1, 1, tzinfo=timezone.utc))
    with pytest.raises(EventInPast):
        sell_ticket(event, "a@example.com")
```

A few details that matter:

- **Overrides win**: `fields | overrides` (Python 3.9+) replaces defaults with whatever the test passes. A typo like `make_event(prise_cents=0)` still fails loudly, because the dataclass rejects unknown keyword arguments.
- **Unique values** come from the counter, so tests that check "two events with different titles" don't collide by accident.
- **`venue if venue is not None`** instead of `venue or ...`: if a dataclass ever defines `__len__` or `__bool__`, `or` would quietly replace a real object.
- **Fixtures, not plain helper functions**: a factory can depend on other fixtures. If Event later needs a database session, change `make_event(make_venue)` to `make_event(make_venue, db_session)` and no test changes.

If the objects later become database rows, the same pattern can clean up after itself with `yield`:

```python
@pytest.fixture
def make_event_row(db_session, make_event):
    created = []

    def _make(**overrides):
        event = make_event(**overrides)
        db_session.add(event)
        db_session.flush()
        created.append(event)
        return event

    yield _make
    for event in created:
        db_session.delete(event)
```

If you end up with many more models, `factory_boy` gives you the same thing with less code (`EventFactory(venue__capacity=2)`), but for three dataclasses the fixtures above are simpler and have no dependency.

how do I unit test retry logic without actually waiting? here's the sender:

```python
# hooks/sender.py
import time

import httpx


class DeliveryFailed(Exception):
    pass


class WebhookSender:
    def __init__(self, client: httpx.Client, max_attempts: int = 3, backoff: float = 0.5) -> None:
        self.client = client
        self.max_attempts = max_attempts
        self.backoff = backoff

    def send(self, url: str, payload: dict) -> httpx.Response:
        for attempt in range(1, self.max_attempts + 1):
            try:
                response = self.client.post(url, json=payload, timeout=5.0)
            except httpx.TransportError:
                if attempt == self.max_attempts:
                    raise
            else:
                if response.status_code < 500:
                    response.raise_for_status()
                    return response
            time.sleep(self.backoff * 2 ** (attempt - 1))
        raise DeliveryFailed(f"{url}: still failing after {self.max_attempts} attempts")
```

I want to cover: connection error then success, 5xx retries, 4xx not retried, giving up.

Hypothesis found a real ambiguity in the format. Trace it by hand:

- `encode("0")` produces `"10"`: count `1`, character `0`.
- `decode("10")` sees two digits, builds `num = "10"`, and the string ends before a non-digit arrives. Nothing is appended, so you get `""`.

As soon as a tile character is a digit, the decoder can't tell counts from tiles. `"0"` is just the smallest example Hypothesis could shrink to. There's a second, related bug: `str.isdigit()` is true for characters like `"²"` or `"٣"`, so a level containing one either loses data or crashes `decode` with a `ValueError` from `int()`.

The fix depends on what levels may contain. Tiles are presumably never digits, so make that a rule: reject digits in `encode`, parse only ASCII digits in `decode`, and make `decode` strict about malformed input instead of silently dropping data:

```python
# levels/rle.py
DIGITS = "0123456789"


def encode(s: str) -> str:
    if any(ch in DIGITS for ch in s):
        raise ValueError("level rows must not contain the digits 0-9")
    if not s:
        return ""
    out = []
    prev, count = s[0], 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{count}{prev}")
            prev, count = ch, 1
    out.append(f"{count}{prev}")
    return "".join(out)


def decode(s: str) -> str:
    out = []
    num = ""
    for ch in s:
        if ch in DIGITS:
            num += ch
        elif not num:
            raise ValueError(f"missing count before {ch!r}")
        else:
            out.append(ch * int(num))
            num = ""
    if num:
        raise ValueError(f"count {num} at the end has no tile")
    return "".join(out)
```

Then let the tests state the rule and check more than the round-trip:

```python
# tests/test_rle.py
import pytest
from hypothesis import example, given, strategies as st

from levels.rle import DIGITS, decode, encode

rows = st.text(alphabet=st.characters(exclude_characters=DIGITS), max_size=300)


@given(rows)
@example("")
@example("w" * 12)  # multi-digit count
def test_roundtrip(s):
    assert decode(encode(s)) == s


@given(rows)
def test_encoding_is_never_more_than_twice_as_long(s):
    assert len(encode(s)) <= 2 * len(s)


@given(rows.filter(bool))
def test_neighbouring_runs_use_different_tiles(s):
    tiles = [ch for ch in encode(s) if ch not in DIGITS]
    assert all(a != b for a, b in zip(tiles, tiles[1:]))


@given(st.text(alphabet=DIGITS, min_size=1))
def test_digits_are_rejected(s):
    with pytest.raises(ValueError):
        encode(s)


@pytest.mark.parametrize("bad", ["w", "3", "2w3", "g4"])
def test_malformed_input_is_an_error(bad):
    with pytest.raises(ValueError):
        decode(bad)
```

A few notes:

- **`@example(...)`** pins cases that always run, in addition to the random ones. Use it for the edge cases you care about, and for any failure Hypothesis finds, so it stays covered.
- **Failures are replayed automatically.** Hypothesis saves them in `.hypothesis/` and tries them first next time. Add that folder to `.gitignore`.
- The extra properties catch bugs the round-trip can't. For example, an encoder that writes `"1w1w"` instead of `"2w"` still round-trips but fails `test_neighbouring_runs_use_different_tiles`.

If digits must be allowed as tiles one day, the format needs a separator or an escape (for example `"3:0"`). Then drop the `exclude_characters` and the round-trip test covers it automatically.

